from scipy.linalg import null_space

old=pd.read_csv('results/fluxes.csv').set_index('reaction_id')
vold=old.loc[NET.reaction_id,'net_flux'].values
A=np.vstack([S,np.eye(1,len(NET),0)]); b=np.r_[np.zeros(len(mets)),100.]
vp=np.linalg.lstsq(A,b,rcond=None)[0]; N=null_space(A)
y0=N.T@(vold-vp)
e0=[]
for j in rev:e0.append(min(old.loc[NET.reaction_id[j],'forward_flux'],old.loc[NET.reaction_id[j],'reverse_flux']))
q0=np.r_[y0,np.log(np.maximum(e0,0.05))]
calls=[0]
def build(q):
    v=vp+N@q[:N.shape[1]]; e=np.exp(q[N.shape[1]:]);f=np.maximum(v,0);r=np.maximum(-v,0)
    for k,j in enumerate(rev):f[j]+=e[k];r[j]+=e[k]
    return f,r,v
def fun(q):
    f,r,v=build(q);out=[]
    for rid,row in RATES.iterrows():
        if row.sd>0:out.append((v[NET.reaction_id.eq(rid).idxmax()]-row.rate)/row.sd)
    out.extend(np.minimum(v[irr],0)/.01)
    for exp in ['glc12','gln5']:
      d=simulate(f,r,exp)
      for (ee,fr),g in groups.items():
        if ee==exp:out.extend((predicted_fragment(d,fr)-g.fraction.values)/g.sd.values)
    calls[0]+=1
    if calls[0]%25==0:print(calls[0],np.sum(np.square(out)),flush=True)
    return np.array(out)
fit=least_squares(fun,q0,max_nfev=500,verbose=2,diff_step=1e-4,x_scale='jac',ftol=1e-10,xtol=1e-10,gtol=1e-10)
f,r,v=build(fit.x)
print('FINAL',sum(fun(fit.x)**2),fit.optimality)
for j,rid in enumerate(NET.reaction_id):print(rid,v[j],f[j],r[j])
pd.DataFrame({'reaction_id':NET.reaction_id,'net_flux':v,'forward_flux':f,'reverse_flux':r}).to_csv('results/fluxes.csv',index=False)

